import django.db.models.deletion
from django.db import migrations, models


def separate_homepage_artwork(apps, schema_editor):
    alias = schema_editor.connection.alias
    Product = apps.get_model("shop", "Product")
    HomepageProductImage = apps.get_model("pages", "HomepageProductImage")
    photos = {"amoxicillin": "capsules", "paracetamol": "tablets",
              "vitamin-c": "vitamins", "omeprazole": "blister-packs"}
    for slug, photo in photos.items():
        for product in Product.objects.using(alias).filter(slug=slug):
            previous_home_image = f"home/photos/{photo}.jpg"
            homepage_image = "home/photos/paracetamol-home.jpg" if slug == "paracetamol" else previous_home_image
            HomepageProductImage.objects.using(alias).get_or_create(
                product_id=product.pk, defaults={"image": homepage_image}
            )
            # Restore only images changed by the earlier visual migration.
            # Never overwrite a subsequently customised shop photograph.
            if product.image == previous_home_image:
                product.image = f"/static/shop/products/{slug}.svg"
                product.save(using=alias, update_fields=["image"])


